using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sets the result of an inline query; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> AnswerInlineQueryAsync(long inlineQueryId = default, bool isPersonal = default, InlineQueryResultsButton button = default, InputInlineQueryResult[] results = default, int cacheTime = default, string nextOffset = default)
    {

           using var activity =  StartCallActivity("AnswerInlineQueryAsync", typeof(AnswerInlineQuery).FullName ?? "AnswerInlineQueryAsync");

           try
           {
             return client.AnswerInlineQueryAsync(inlineQueryId, isPersonal, button, results, cacheTime, nextOffset);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
